const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const subject = j.subject || '(no subject)';
  const from = j.from?.value?.[0]?.address || j.from || 'unknown';
  const snippet = [j.snippet, j.textPlain, j.bodyPlain].filter(Boolean).join('\n').slice(0, 400);
  const combined = `${subject}\n${snippet}`;

  let priority = 'P3';
  if (/urgent|down|outage|asap/i.test(combined)) priority = 'P1';
  else if (/invoice|billing|refund|payment/i.test(combined)) priority = 'P2';

  out.push({
    json: {
      chatId: 'REPLACE_CHAT_ID',
      telegramText: [
        `Support ticket ${priority}`,
        `From: ${from}`,
        `Subject: ${subject}`,
        '',
        snippet || '(no preview)'
      ].join('\n')
    }
  });
}
return out;
